L000030	\title{
L000031	Symmetry-controlled thermal activation in pyramidal Coulomb clusters:\\ Testing Kramers-Langer theory
L000032	}
L000033	
L000034	
L000035	\author{Akhil Ayyadevara}
L000036	%\email{akhilv@rri.res.in}
L000037	\affiliation{Raman Research Institute, C. V. Raman Avenue, Sadashivanagar, Bangalore 560080, India}
L000038	\author{Anand Prakash}%
